properties.query:
// Microsoft Sentinel — auto-derived from the Defender XDR hunt.
// Requires the Microsoft 365 Defender data connector (streams the
// advanced-hunting tables into Sentinel; Timestamp → TimeGenerated).
let LookbackDays = 7d;
let Window = 10m;
let MetadataIps = dynamic(["169.254.169.254","fd00:ec2::254"]);
let C2 = dynamic([<c2_ip_list>]);
let ServerRuntimes = dynamic(["java.exe","javaw.exe","node.exe","ruby.exe","python.exe","python3","php-fpm","w3wp.exe","nginx.exe","httpd"]);
let Inbound = DeviceNetworkEvents
    | where TimeGenerated > ago(LookbackDays)
    | where ActionType == "InboundConnectionAccepted"
    | where RemoteIPType == "Public"
    | project InboundTime = TimeGenerated, DeviceId, DeviceName, LocalPort;
DeviceNetworkEvents
| where TimeGenerated > ago(LookbackDays)
| where ActionType == "ConnectionSuccess"
| where RemoteIP in (MetadataIps) or RemoteIP in (C2)
| where InitiatingProcessFileName in~ (ServerRuntimes)
| join kind=inner Inbound on DeviceId
| where TimeGenerated between (InboundTime .. InboundTime + Window)   // egress within 10m of an inbound public hit
| project TimeGenerated, DeviceName, ServerProcess = InitiatingProcessFileName,
          InitiatingProcessCommandLine, RemoteIP, RemotePort,
          InboundTime, DelaySec = datetime_diff('second', TimeGenerated, InboundTime)
| order by TimeGenerated desc
